import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ApplianceGrinderProps = Record<string, any>;

// Subcomponent for reusable Grinder Gear
const Gear = ({ x, y, rotation, color }: { x: number; y: number; rotation: number; color: string }) => {
  const circum = 2 * Math.PI * 90; 
  const teethCount = 12;
  const segmentLength = circum / teethCount; 
  const dashLength = segmentLength * 0.6; 
  const gapLength = segmentLength * 0.4;

  return (
    <div style={{
      position: 'absolute',
      left: x,
      top: y,
      width: 200,
      height: 200,
      transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      transition: "none"
    }}>
      <svg width="200" height="200" viewBox="0 0 200 200" style={{ transition: "none" }}>
        <circle cx="100" cy="100" r="70" fill={color} />
        <circle 
          cx="100" 
          cy="100" 
          r="90" 
          fill="transparent" 
          stroke={color} 
          strokeWidth="20" 
          strokeDasharray={`${dashLength} ${gapLength}`} 
        />
        <circle cx="100" cy="100" r="30" fill="#0f172a" />
      </svg>
    </div>
  );
};

const ApplianceGrinder: React.FC<ApplianceGrinderProps> = ({
  backgroundColor = "#f1f5f9",
  transparentBackground = false,
  durationInSeconds = 10,
  applianceSpeed = 1.0,
  grinderSpeed = 5,
  grinderSize = 1.0,
  particleCount = 50,
  grinderColor = "#475569",
  appliances = ["📺", "📻", "🕰️", "🔌", "💻", "🖨️", "📱", "🕹️", "💡"],
  metalColors = ["#94a3b8", "#cbd5e1", "#e2e8f0", "#64748b"],
  plasticColors = ["#ef4444", "#3b82f6", "#22c55e", "#eab308", "#d946ef", "#f97316"]
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Playfair Display"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const totalFrames = fps * durationInSeconds;

  const safeAppliances = appliances.length > 0 ? appliances : ["📦"];
  const safeMetalColors = metalColors.length > 0 ? metalColors : ["#94a3b8"];
  const safePlasticColors = plasticColors.length > 0 ? plasticColors : ["#ef4444"];
  const combinedColors = [...safeMetalColors, ...safePlasticColors];

  // Timing Configuration
  const dropDuration = Math.max(10, Math.floor(45 / applianceSpeed));
  const spawnInterval = Math.max(10, Math.floor(dropDuration * 1.2));
  const numAppliances = Math.ceil(totalFrames / spawnInterval);

  // Pre-calculate randomized parameters to maintain strict monotonic logic & extreme performance
  const appliancesConfig = React.useMemo(() => {
    return Array.from({ length: numAppliances }).map((_, i) => {
      const startFrame = i * spawnInterval;
      const hitFrame = startFrame + dropDuration;
      const emoji = safeAppliances[i % safeAppliances.length];
      const xOffset = interpolate(random(`x-${i}`), [0, 1], [-40, 40]);
      const rotFactor = random(`rot-${i}`);
      return { id: i, startFrame, hitFrame, emoji, xOffset, rotFactor };
    });
  }, [numAppliances, spawnInterval, dropDuration, safeAppliances]);

  const particlesConfig = React.useMemo(() => {
    return appliancesConfig.map(app => {
      return Array.from({ length: particleCount }).map((_, p) => {
        const seed = `${app.id}-${p}`;
        const angle = interpolate(random(`angle-${seed}`), [0, 1], [Math.PI * 0.1, Math.PI * 0.9]);
        const velocity = interpolate(random(`vel-${seed}`), [0, 1], [5, 25]);
        const pxOffset = interpolate(random(`px-${seed}`), [0, 1], [-30, 30]);
        const isCircle = random(`shape-${seed}`) > 0.5;
        const pSize = interpolate(random(`size-${seed}`), [0, 1], [6, 20]);
        const aspect = interpolate(random(`aspect-${seed}`), [0, 1], [0.3, 1]);
        const pColor = combinedColors[Math.floor(random(`color-${seed}`) * combinedColors.length)];
        const rotFactor = interpolate(random(`rot-${seed}`), [0, 1], [-15, 15]);

        return { angle, velocity, pxOffset, isCircle, pSize, aspect, pColor, rotFactor };
      });
    });
  }, [appliancesConfig, particleCount, combinedColors]);

  // Gear Rotation Logic
  const leftRot = frame * grinderSpeed * 1.5;
  const rightRot = -frame * grinderSpeed * 1.5 + 15;

  // Render constants
  const centerY = height * 0.5;
  const centerX = width * 0.5;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Playfair Display", transition: "none" }}>
      
      {!transparentBackground && (
        <>
          <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: 24, background: 'repeating-linear-gradient(45deg, #eab308, #eab308 30px, #000 30px, #000 60px)', opacity: 0.9, transition: "none" }} />
          <div style={{ position: 'absolute', bottom: 0, left: 0, width: '100%', height: 24, background: 'repeating-linear-gradient(-45deg, #eab308, #eab308 30px, #000 30px, #000 60px)', opacity: 0.9, transition: "none" }} />
        </>
      )}

      {/* Background Studio Label */}
      <div style={{ 
        position: 'absolute', 
        top: 80, 
        width: '100%', 
        textAlign: 'center', 
        color: grinderColor, 
        fontSize: 32, 
        fontWeight: 700, 
        opacity: 0.2,
        letterSpacing: 4,
        transition: "none" 
      }}>
        MALLOY STUDIO | RECYCLING FACILITY
      </div>

      {/* Layer 1: Hopper Back */}
      <div style={{ position: 'absolute', left: centerX, top: centerY, transform: `scale(${grinderSize})`, transition: 'none' }}>
        <svg style={{ position: 'absolute', top: -150, left: -200, transition: 'none' }} width="400" height="150" viewBox="0 0 400 150">
          <polygon points="50,0 350,0 240,150 160,150" fill="#0f172a" />
        </svg>
      </div>

      {/* Layer 2: Falling Appliances */}
      {appliancesConfig.map((app) => {
        const t = frame - app.startFrame;
        if (t < 0 || t > dropDuration) return null;

        const startY = -250;
        const endY = centerY - 20 * grinderSize;
        const currentY = interpolate(t, [0, dropDuration], [startY, endY]);
        
        const scaleStartFrame = Math.max(0, dropDuration - 10);
        const scale = interpolate(t, [scaleStartFrame, dropDuration], [1, 0], { 
          extrapolateLeft: "clamp", 
          extrapolateRight: "clamp" 
        });
        
        const rot = interpolate(t, [0, dropDuration], [0, app.rotFactor * 360]);

        return (
          <div key={`app-${app.id}`} style={{
            position: 'absolute',
            left: centerX + app.xOffset * grinderSize,
            top: currentY,
            transform: `translate(-50%, -50%) rotate(${rot}deg) scale(${scale})`,
            fontSize: 100,
            transition: "none",
            filter: "drop-shadow(0px 10px 15px rgba(0,0,0,0.3))"
          }}>
            {app.emoji}
          </div>
        );
      })}

      {/* Layer 3: Grinder Gears */}
      <div style={{ position: 'absolute', left: centerX, top: centerY, transform: `scale(${grinderSize})`, transition: 'none' }}>
        <Gear x={-80} y={0} rotation={leftRot} color={grinderColor} />
        <Gear x={80} y={0} rotation={rightRot} color={grinderColor} />
      </div>

      {/* Layer 4: Hopper Front Rim (Covers the appliance as it falls in) */}
      <div style={{ position: 'absolute', left: centerX, top: centerY, transform: `scale(${grinderSize})`, transition: 'none' }}>
        <svg style={{ position: 'absolute', top: -150, left: -200, transition: 'none' }} width="400" height="150" viewBox="0 0 400 150">
          <path d="M 0 0 L 140 150 L 260 150 L 400 0 L 370 0 L 250 120 L 150 120 L 30 0 Z" fill={grinderColor} />
        </svg>
      </div>

      {/* Layer 5: Particles (Exiting from the bottom of the gears) */}
      {appliancesConfig.map((app, i) => {
        const t = frame - app.hitFrame;
        if (t < 0 || t > 180) return null; // Particle lifespan before fully off-screen

        const appParticles = particlesConfig[i];
        
        return (
          <React.Fragment key={`parts-${app.id}`}>
            {appParticles.map((pt, p) => {
              const pX = centerX + Math.cos(pt.angle) * pt.velocity * t + pt.pxOffset * grinderSize;
              // Particles start just below the scaled gear meshing point
              const pY = (centerY + 40 * grinderSize) + Math.sin(pt.angle) * pt.velocity * t + 0.5 * 0.8 * t * t;
              const rot = t * pt.rotFactor;

              return (
                <div key={p} style={{
                  position: 'absolute',
                  left: pX,
                  top: pY,
                  width: pt.pSize,
                  height: pt.isCircle ? pt.pSize : pt.pSize * pt.aspect,
                  backgroundColor: pt.pColor,
                  borderRadius: pt.isCircle ? '50%' : '4px',
                  transform: `translate(-50%, -50%) rotate(${rot}deg)`,
                  transition: "none",
                  boxShadow: "0px 2px 5px rgba(0,0,0,0.2)"
                }} />
              );
            })}
          </React.Fragment>
        );
      })}

    </AbsoluteFill>
  );
};

export default ApplianceGrinder;